    private const string CorpusSha256 = "79f6e77e4138402b8ab046083fdc72614121f4f121853602f042bf98c11bcc69";

    internal static JsonDocument Corpus()
    {
        byte[] bytes = Inflate(Convert.FromBase64String(CorpusBase64), 2_000_000);
        if (Convert.ToHexStringLower(SHA256.HashData(bytes)) != CorpusSha256)
            throw new InvalidDataException("Frozen independent corpus changed");
        var document = JsonDocument.Parse(bytes);
        foreach (var property in document.RootElement.GetProperty("source_pins").EnumerateObject())
        {
            var value = document.RootElement.GetProperty(property.Name);
            string expected = property.Value.GetString()!;
            byte[] original = Inflate(Convert.FromBase64String(value.GetProperty("original_json_gzip_base64").GetString()!), 10_000_000);
            if (Convert.ToHexStringLower(SHA256.HashData(original)) != expected)
                throw new InvalidDataException("Individual independent JSON source pin changed");
        }
        return document;
    }

    private static byte[] Inflate(byte[] compressed, int limit)
    {
        using var input = new MemoryStream(compressed);
        using var gzip = new GZipStream(input, CompressionMode.Decompress);
        using var output = new MemoryStream();
        byte[] buffer = new byte[8192];
        int n;
        while ((n = gzip.Read(buffer)) != 0)
        {
            if (output.Length + n > limit) throw new InvalidDataException("Independent corpus expansion exceeded its bound");
            output.Write(buffer, 0, n);
        }
        return output.ToArray();
    }

    internal static JsonElement Data(JsonElement wrapper)
    {
        using var document = JsonDocument.Parse(Inflate(Convert.FromBase64String(wrapper.GetProperty("original_json_gzip_base64").GetString()!), 10_000_000));
        return document.RootElement.Clone();
    }
    internal static byte[] Bytes(JsonElement image) => Convert.FromBase64String(image.GetProperty("base64").GetString()!);
    internal static ulong Hex(string text) => Convert.ToUInt64(text, 16);
    internal static RetailRandomState State(byte[] bytes)
    {
        Assert.True(RetailRandomState.TryCreate(bytes, Convert.ToHexStringLower(SHA256.HashData(bytes)), out var state, out _));
        Assert.NotNull(state); return state;
    }
    internal static RetailRandomState State(JsonElement image) => State(Bytes(image));

    internal static RetailRandomOwnershipDeclaration Ownership(RetailRandomInputOrigin origin = RetailRandomInputOrigin.ConstructedFixture, ulong generation = 0) =>
        new(origin, "fixture-stream", "fixture-life", "fixture-order", "declared-acquisition-no-runtime-attestation",
            0x1518fb8d0, generation, true);
    internal static RetailRandomSourceDeclaration Sources => new(RetailRandomEngine.MainBinarySha256, RetailRandomEngine.RngEvidenceSha256);
    internal static RetailRandomDescriptorDeclaration Descriptor => new(0x1518fb8d0, 64, ulong.MaxValue);
    internal static RetailRandomSeedReturnDeclaration Seed(uint value, int ordinal, ulong generation,
        RetailRandomInputOrigin origin = RetailRandomInputOrigin.ConstructedFixture) =>
        new(RetailRandomSeedReturnKind.NormalReturn, value, origin, "fixture-stream", "fixture-life", "fixture-order",
            $"request-{ordinal}", generation, 0x140013959, "declared-original-seed-return-not-executed");
    internal static RetailRandomOperation Operation(int ordinal, RetailRandomOperationKind kind, int first = 0,
        int second = 0, uint bound = 0, ulong discard = 0, uint? seed = null, ulong initialGeneration = 0,
        RetailRandomInputOrigin origin = RetailRandomInputOrigin.ConstructedFixture) =>
        new(ordinal, $"request-{ordinal}", kind, initialGeneration + (ulong)ordinal, first, second, bound, discard,
            seed is uint value ? Seed(value, ordinal, initialGeneration + (ulong)ordinal, origin) : null);
    internal static RetailRandomTransaction Transaction(byte[] bytes, params RetailRandomOperation[] operations) =>
        new(RetailRandomInputOrigin.ConstructedFixture, 0, ImmutableArray.CreateRange(operations),
            ImmutableArray.CreateRange(bytes), Convert.ToHexStringLower(SHA256.HashData(bytes)), Sources, Ownership(), Descriptor,
            new RetailRandomLimits());

    internal static void Trace(JsonElement expected, RetailRandomDrawTrace actual, int operationOrdinal, bool? accepted = null)
    {
        Assert.Equal(operationOrdinal, actual.OperationOrdinal);
        Assert.Equal(expected.GetProperty("index_before").GetUInt32(), actual.IndexBefore);
        Assert.Equal(expected.GetProperty("selected_index").GetUInt32(), actual.SelectedIndex);
        Assert.Equal(expected.GetProperty("index_after").GetUInt32(), actual.IndexAfter);
        Assert.Equal(Hex(expected.GetProperty("raw_u64").GetString()!), actual.Value);
        Assert.Equal(expected.GetProperty("stage").GetString(), actual.Regeneration.ToString());
        if (accepted is bool value) Assert.Equal(value ? RetailRandomDrawDisposition.Accepted : RetailRandomDrawDisposition.Rejected, actual.Disposition);
    }

    internal static void NoExecutionClaims(RetailRandomTransactionResult result)
    {
        Assert.False(result.HostEffectsExecuted); Assert.False(result.OriginalSeedProviderExecuted);
        Assert.False(result.CurrentMemoryAcquisitionAttested); Assert.False(result.GlobalNativeCallOrderProved);
        Assert.False(result.CompleteNativeStartupReplayed); Assert.False(result.ActivationReady);
    }
}
